import type { Metadata } from "next";
import { Lang, localePath } from "@/lib/i18n";
import { SITE_NAME } from "@/lib/site";

// Default share image (generated by src/app/og.png/route.tsx)
export const DEFAULT_OG_IMAGE = {
  url: "/og.png",
  width: 1200,
  height: 630,
  alt: "Hannes Täyrönen: builder, founder, explorer",
};

const OG_LOCALE: Record<Lang, string> = { en: "en_US", fi: "fi_FI" };

interface PageSeo {
  lang: Lang; // language of this URL
  path: string; // path without the /fi prefix, e.g. "/think"
  title?: string; // leave out to use the site name
  description: string;
  // Languages this page exists in. A page in both gets hreflang links between them.
  languages?: Lang[];
  // Language the content is written in, if different from the URL's
  // (a one-language post shown under the other language's URL).
  contentLang?: Lang;
  image?: string;
  publishedTime?: string;
}

// Full metadata for one page. Next.js replaces (doesn't merge) openGraph from the
// layout when a page sets it, so every page gets the complete set from here.
export function pageMetadata({
  lang,
  path,
  title,
  description,
  languages = ["en", "fi"],
  contentLang = lang,
  image,
  publishedTime,
}: PageSeo): Metadata {
  const canonical = localePath(contentLang, path);
  const hasBoth = languages.includes("en") && languages.includes("fi");

  return {
    // Only set when given: an explicit undefined would wipe out the layout's default title
    ...(title && { title }),
    description,
    alternates: {
      canonical,
      languages: hasBoth
        ? { en: localePath("en", path), fi: localePath("fi", path), "x-default": localePath("en", path) }
        : undefined,
    },
    openGraph: {
      type: publishedTime ? "article" : "website",
      url: canonical,
      siteName: SITE_NAME,
      locale: OG_LOCALE[contentLang],
      title: title ?? SITE_NAME,
      description,
      images: image ? [image] : [DEFAULT_OG_IMAGE],
      ...(publishedTime && { publishedTime, authors: [SITE_NAME] }),
    },
  };
}
